// Build the compact country files in this folder from Natural Earth GeoJSON.
// Usage: node vendor/natural-earth/build.mjs <ne_110m_admin_0_countries.geojson> <out.js|out.json> [decimals]
// Keeps a few properties, rounds coordinates and drops repeated points. A .js
// output is a classic script that sets globalThis.HFNaturalEarth[<file name>],
// so a composition loads it with a <script> tag and no fetch. See UPSTREAM.md.
import { readFileSync, writeFileSync } from "node:fs";
import { basename } from "node:path";

const [input, output, dec = "2"] = process.argv.slice(2);
if (!input || !output) {
  console.error("usage: build.mjs <input.geojson> <output.json> [decimals]");
  process.exit(1);
}
const k = 10 ** Number(dec);
const round = (n) => Math.round(n * k) / k;

function ring(r) {
  const out = [];
  for (const [x, y] of r) {
    const p = [round(x), round(y)];
    const last = out[out.length - 1];
    if (!last || last[0] !== p[0] || last[1] !== p[1]) out.push(p);
  }
  if (out.length > 1) {
    const a = out[0];
    const b = out[out.length - 1];
    if (a[0] !== b[0] || a[1] !== b[1]) out.push([a[0], a[1]]);
  }
  return out.length >= 4 ? out : null;
}
const poly = (p) => {
  const rings = p.map(ring).filter(Boolean);
  return rings.length ? rings : null;
};

const src = JSON.parse(readFileSync(input, "utf8"));
const features = [];
for (const f of src.features) {
  const g = f.geometry;
  const polys = (g.type === "Polygon" ? [g.coordinates] : g.coordinates).map(poly).filter(Boolean);
  if (!polys.length) continue;
  const p = f.properties;
  const iso = p.ISO_A3_EH !== "-99" ? p.ISO_A3_EH : p.ADM0_A3;
  features.push({
    type: "Feature",
    id: iso,
    properties: {
      name: p.NAME,
      iso_a3: iso,
      continent: p.CONTINENT,
      subregion: p.SUBREGION,
      label: [round(p.LABEL_X), round(p.LABEL_Y)],
    },
    geometry:
      polys.length === 1
        ? { type: "Polygon", coordinates: polys[0] }
        : { type: "MultiPolygon", coordinates: polys },
  });
}
features.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
const json = JSON.stringify({
  type: "FeatureCollection",
  source: "Natural Earth admin 0 countries (public domain), see vendor/natural-earth/UPSTREAM.md",
  features,
});
const key = basename(output).replace(/\.(js|json)$/, "");
writeFileSync(
  output,
  output.endsWith(".js")
    ? "// Generated by vendor/natural-earth/build.mjs from Natural Earth (public domain).\n" +
        "(globalThis.HFNaturalEarth = globalThis.HFNaturalEarth || {})[" + JSON.stringify(key) + "] = " + json + ";\n"
    : json + "\n",
);
console.log(output, features.length, "features");
